# Precompute cell candidates per each piece placements
all_solutions=[]
def solve(usedcells=frozenset(), usedpieces=frozenset(), chosen={}):
 if len(usedpieces)==len(dims):
  if usedcells==frozenset(slots): all_solutions.append(chosen.copy())
  return
 remaining=slots-usedcells
 # choose most constrained uncovered target cell from placements of unused pieces
 best=None; candbest=None
 for cell in remaining:
  cand=[]
  for name in dims:
   if name in usedpieces: continue
   for p in opts[name]:
    if cell in p[4] and not (p[4]&usedcells): cand.append((name,p))
  if not cand:return
  if candbest is None or len(cand)<len(candbest): best,candbest=cell,cand
  if len(candbest)==1:break
 for name,p in candbest:
  chosen[name]=p
  solve(usedcells|p[4],usedpieces|{name},chosen)
  chosen.pop(name)
